function arrayPairSum(nums) {
  // Try every way to pair the first unused element with another unused one.
  const used = new Array(nums.length).fill(false);
  const search = () => {
    let first = -1;
    for (let i = 0; i < nums.length; i++) if (!used[i]) { first = i; break; }
    if (first === -1) return 0;
    used[first] = true;
    let bestScore = -Infinity;
    for (let j = first + 1; j < nums.length; j++) {
      if (used[j]) continue;
      used[j] = true;
      const score = Math.min(nums[first], nums[j]) + search();
      if (score > bestScore) bestScore = score;
      used[j] = false;
    }
    used[first] = false;
    return bestScore;
  };
  return search();
}

